#include <iostream>
#include <map>
#include <vector>
using namespace std;

const int MOD = 1000000007;

struct ModNumber {
    int value;

    ModNumber(long long v = 0) {
        if (v < 0) v %= MOD, v += MOD;
        if (v >= MOD) v %= MOD;
        value = v;
    }

    static int modInverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return value; }

    ModNumber& operator+=(const ModNumber &other) {
        value += other.value;
        if (value >= MOD) value -= MOD;
        return *this;
    }

    ModNumber& operator-=(const ModNumber &other) {
        value -= other.value;
        if (value < 0) value += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
    #if !defined(_WIN32) || defined(_WIN64)
        return x % m;
    #endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    ModNumber& operator*=(const ModNumber &other) {
        value = fast_mod((uint64_t) value * other.value);
        return *this;
    }

    ModNumber& operator/=(const ModNumber &other) {
        return *this *= ModNumber(modInverse(other.value));
    }

    friend ModNumber operator+(const ModNumber &a, const ModNumber &b) { return ModNumber(a) += b; }
    friend ModNumber operator-(const ModNumber &a, const ModNumber &b) { return ModNumber(a) -= b; }
    friend ModNumber operator*(const ModNumber &a, const ModNumber &b) { return ModNumber(a) *= b; }
    friend ModNumber operator/(const ModNumber &a, const ModNumber &b) { return ModNumber(a) /= b; }

    ModNumber& operator++() {
        value = value == MOD - 1 ? 0 : value + 1;
        return *this;
    }

    ModNumber& operator--() {
        value = value == 0 ? MOD - 1 : value - 1;
        return *this;
    }

    ModNumber operator++(int) { ModNumber before = *this; ++*this; return before; }
    ModNumber operator--(int) { ModNumber before = *this; --*this; return before; }

    ModNumber operator-() const {
        return value == 0 ? 0 : MOD - value;
    }

    bool operator==(const ModNumber &other) const { return value == other.value; }
    bool operator!=(const ModNumber &other) const { return value != other.value; }

    ModNumber inv() const {
        return ModNumber(modInverse(value));
    }

    ModNumber pow(long long p) const {
        assert(p >= 0);
        ModNumber base = *this, result = 1;
        while (p > 0) {
            if (p & 1)
                result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

const int MAX_N = 7;

int N;
ModNumber prob[MAX_N][MAX_N];

int main() {
    cin >> N;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p;
            cin >> p;
            prob[i][j] = ModNumber(p) / ModNumber(100);
        }

    map<vector<bool>, ModNumber> states;
    vector<bool> init_mask(1 << N, false);
    init_mask[0] = true;
    states[init_mask] = 1;
    vector<bool> temp_mask;

    for (int left_idx = 0; left_idx < N; left_idx++) {
        map<vector<bool>, ModNumber> new_states_map;
        for (int mask_curr = 0; mask_curr < (1 << N); mask_curr++) {
            ModNumber product = 1;
            for (int right_idx = 0; right_idx < N; right_idx++)
                product *= (mask_curr >> right_idx & 1) ? prob[left_idx][right_idx] : ModNumber(1) - prob[left_idx][right_idx];

            for (auto &entry : states) {
                const vector<bool> &possible_mask = entry.first;
                ModNumber prob_value = entry.second;
                temp_mask.assign(1 << N, false);
                for (int m = 0; m < (1 << N); m++)
                    if (possible_mask[m])
                        for (int i = 0; i < N; i++)
                            if ((mask_curr >> i & 1) != 0 && (m >> i & 1) == 0)
                                temp_mask[m | (1 << i)] = true;

                new_states_map[temp_mask] += prob_value * product;
            }
        }
        states = new_states_map;
    }

    ModNumber total = 0;
    for (auto &p : states)
        if (p.first[(1 << N) - 1])
            total += p.second;

    cout << (int) total << '\n';
}
